/** Material Symbols Rounded (weight 400, optical size 24); filled uses fill1, outlined uses the default. */
object AppIcons {

    private fun icon(name: String, paths: List<String>, evenOdd: Boolean = false): ImageVector =
        ImageVector.Builder(
            name = name,
            defaultWidth = 24.dp,
            defaultHeight = 24.dp,
            viewportWidth = 960f,
            viewportHeight = 960f
        ).apply {
            addGroup(translationY = 960f)
            paths.forEach { d ->
                addPath(
                    pathData = PathParser().parsePathString(d).toNodes(),
                    pathFillType = if (evenOdd) PathFillType.EvenOdd else PathFillType.NonZero,
                    fill = SolidColor(Color.Black)
                )
            }
            clearGroup()
        }.build()

